package com.johnny.hotel.finance;import com.johnny.hotel.common.Result;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/finance/daily-summaries") @RequiredArgsConstructor @PreAuthorize("hasAnyRole('FINANCE','OWNER','SUPER_ADMIN')") public class DailyFinancialSummaryController {private final RevenueRecognitionService service;@GetMapping public Result<List<DailyFinancialSummary>> list(){return Result.success(service.summaries());}@GetMapping("/{date}") public Result<DailyFinancialSummary> one(@PathVariable LocalDate date){return Result.success(service.summary(date));}}
